    "kabDoctor": [
      "Heart Attack (Heart Attack) ke lakshan shuru hote hi bina deri kiye nazdeeki hospital ya doctor se milein.",
      "Agar tez bukhar, saans lene me dikkat, behoshi ya asahaniya dard ho to turant emergency (108 / 112) par call karein.",
      "Chakkar aana, khoon aana, shareer thanda padna ya bolne-chalne me ladkhadahat dikhe to turant medical care lein.",
      "Agar mareez bachha, buzurg, pregnant mahila ya pehle se kisi bimari se peedit hai to bilkul wait na karein.",
      "Doctor ki janch aur test ke bina koi bhi faisla na lein."
    ],
